import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const tokens = readFileSync(join(root, "src/tokens.css"), "utf8").trimEnd();
const primitives = readFileSync(join(root, "src/primitives.css"), "utf8")
  .replace(/^@import\s+["']\.\/tokens\.css["']\s*;\s*/m, "")
  .trim();

const banner = `/* @miquelt9/pc-ui — single-file stylesheet for vanilla <link> usage.
 * Generated by scripts/bundle-css.mjs — do not edit by hand.
 * Source: src/tokens.css + src/primitives.css
 */
`;

writeFileSync(join(root, "src/pc-ui.css"), `${banner}\n${tokens}\n\n${primitives}\n`);
console.log("wrote src/pc-ui.css");
